//
// X11 window input from the server's real input path (issue #10). window_x11_input_tests sends
// synthetic events with XSendEvent, which skips the server's focus, grab, pointer-containment and
// keymap logic. This test drives the same window with the XTEST extension (what xdotool uses), so
// events are generated by the X server itself: the pointer moves over a mapped window, buttons and
// the wheel go to it, and keys reach it through the real focus rules. It skips when there is no
// DISPLAY or no XTEST extension.

#include "tessera/hal/window.hpp"
#include "tessera/ui/input.hpp"
#include "tessera/ui/key_code.hpp"

#include <X11/Xlib.h>
#include <X11/extensions/XTest.h>
#include <X11/keysym.h>
#include <chrono>
#include <cstdlib>
#include <iostream>
#include <string>
#include <string_view>
#include <unistd.h>
#include <vector>

namespace {

using tessera::ui::InputEvent;
using tessera::ui::InputEventType;
using tessera::ui::Modifier;
using tessera::ui::PointerButton;

bool expect(bool condition, const char* message) {
    if (!condition) {
        std::cerr << "window_x11_real_input: " << message << "\n";
    }
    return condition;
}

bool approx(float value, float expected) {
    return value >= expected - 1.5F && value <= expected + 1.5F;
}

::Window find_window(Display* display, ::Window window, std::string_view title) {
    char* name = nullptr;
    if (XFetchName(display, window, &name) != 0 && name != nullptr) {
        const bool matches = title == name;
        XFree(name);
        if (matches) {
            return window;
        }
    }
    ::Window root = 0;
    ::Window parent = 0;
    ::Window* children = nullptr;
    unsigned int child_count = 0;
    if (XQueryTree(display, window, &root, &parent, &children, &child_count) == 0) {
        return 0;
    }
    ::Window found = 0;
    for (unsigned int i = 0; i < child_count && found == 0; ++i) {
        found = find_window(display, children[i], title);
    }
    if (children != nullptr) {
        XFree(children);
    }
    return found;
}

// Everything the window queued, pumped until the queue has been quiet for a moment: the server
// delivers asynchronously, and a real pointer move can also produce enter and crossing events.
std::vector<InputEvent> drain(tessera::hal::Window& window, tessera::ui::InputQueue& queue) {
    std::vector<InputEvent> events;
    const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    int quiet_rounds = 0;
    while (quiet_rounds < 2 && std::chrono::steady_clock::now() < deadline) {
        window.wait_for_events(0.1);
        bool any = false;
        InputEvent event;
        while (queue.pop(event)) {
            events.push_back(event);
            any = true;
        }
        quiet_rounds = any ? 0 : quiet_rounds + 1;
    }
    return events;
}

const InputEvent* first_of(const std::vector<InputEvent>& events, InputEventType type) {
    for (const InputEvent& event : events) {
        if (event.type == type) {
            return &event;
        }
    }
    return nullptr;
}

struct Server {
    Display* display;
    ::Window native;
    int origin_x;
    int origin_y;

    void flush() const {
        XFlush(display);
        XSync(display, False);
    }
    void move(int x, int y) const {
        XTestFakeMotionEvent(display, DefaultScreen(display), origin_x + x, origin_y + y, 0);
        flush();
    }
    void button(unsigned button, bool press) const {
        XTestFakeButtonEvent(display, button, press ? True : False, 0);
        flush();
    }
    void key(KeySym keysym, bool press) const {
        XTestFakeKeyEvent(display, XKeysymToKeycode(display, keysym), press ? True : False, 0);
        flush();
    }
};

bool wait_until_viewable(Display* display, ::Window native, tessera::hal::Window& window) {
    for (int i = 0; i < 40; ++i) {
        XWindowAttributes attributes{};
        XGetWindowAttributes(display, native, &attributes);
        if (attributes.map_state == IsViewable) {
            return true;
        }
        window.wait_for_events(0.05);
    }
    return false;
}

bool pointer_and_wheel(const Server& server, tessera::hal::Window& window,
                       tessera::ui::InputQueue& queue, float scale) {
    server.move(10, 10);
    (void)drain(window, queue);

    server.move(96, 48);
    std::vector<InputEvent> events = drain(window, queue);
    const InputEvent* move = first_of(events, InputEventType::PointerMove);
    if (!expect(move != nullptr, "a real pointer move becomes a PointerMove") ||
        !expect(approx(move->x, 96.0F / scale) && approx(move->y, 48.0F / scale),
                "the move carries logical window coordinates")) {
        return false;
    }

    server.button(Button1, true);
    events = drain(window, queue);
    const InputEvent* down = first_of(events, InputEventType::PointerDown);
    if (!expect(down != nullptr && down->button == PointerButton::Left,
                "a real left press is a PointerDown")) {
        return false;
    }
    server.button(Button1, false);
    events = drain(window, queue);
    const InputEvent* up = first_of(events, InputEventType::PointerUp);
    if (!expect(up != nullptr && up->button == PointerButton::Left,
                "a real left release is a PointerUp")) {
        return false;
    }

    server.button(Button5, true);
    server.button(Button5, false);
    events = drain(window, queue);
    const InputEvent* wheel = first_of(events, InputEventType::Wheel);
    if (!expect(wheel != nullptr && wheel->dy > 0.0F && wheel->dx == 0.0F,
                "a real wheel notch down is a Wheel with the web sign") ||
        !expect(first_of(events, InputEventType::PointerDown) == nullptr,
                "a wheel notch is not also a click")) {
        return false;
    }
    return true;
}

bool keyboard(const Server& server, tessera::hal::Window& window, tessera::ui::InputQueue& queue) {
    XSetInputFocus(server.display, server.native, RevertToParent, CurrentTime);
    server.flush();
    (void)drain(window, queue);

    server.key(XK_a, true);
    std::vector<InputEvent> events = drain(window, queue);
    const InputEvent* key_down = first_of(events, InputEventType::KeyDown);
    const InputEvent* text = first_of(events, InputEventType::Text);
    if (!expect(key_down != nullptr && key_down->key == 'A' && !key_down->repeat,
                "a real key press is a KeyDown 'A'") ||
        !expect(text != nullptr && text->text_codepoint == 'a', "it types 'a'")) {
        return false;
    }
    server.key(XK_a, false);
    events = drain(window, queue);
    const InputEvent* key_up = first_of(events, InputEventType::KeyUp);
    if (!expect(key_up != nullptr && key_up->key == 'A', "a real release is a KeyUp 'A'")) {
        return false;
    }

    server.key(XK_Shift_L, true);
    server.key(XK_a, true);
    events = drain(window, queue);
    text = first_of(events, InputEventType::Text);
    bool shifted = false;
    for (const InputEvent& event : events) {
        if (event.type == InputEventType::KeyDown && event.key == 'A' &&
            tessera::ui::has_modifier(event.modifiers, Modifier::Shift)) {
            shifted = true;
        }
    }
    const bool typed_capital = text != nullptr && text->text_codepoint == 'A';
    server.key(XK_a, false);
    server.key(XK_Shift_L, false);
    (void)drain(window, queue);
    if (!expect(shifted, "Shift is reported as a modifier on the real key event") ||
        !expect(typed_capital, "Shift+a types 'A'")) {
        return false;
    }

    server.key(XK_Left, true);
    events = drain(window, queue);
    const InputEvent* arrow = first_of(events, InputEventType::KeyDown);
    const bool no_text = first_of(events, InputEventType::Text) == nullptr;
    server.key(XK_Left, false);
    (void)drain(window, queue);
    return expect(arrow != nullptr && arrow->key == tessera::ui::key::kArrowLeft && no_text,
                  "a real left arrow maps to kArrowLeft and types nothing");
}

} // namespace

int main() {
    const char* display_name = std::getenv("DISPLAY");
    if (display_name == nullptr || display_name[0] == '\0') {
        std::cout << "window_x11_real_input: skipped (DISPLAY is not set)\n";
        return 0;
    }
    Display* display = XOpenDisplay(nullptr);
    if (display == nullptr) {
        std::cout << "window_x11_real_input: skipped (cannot open DISPLAY)\n";
        return 0;
    }
    int event_base = 0;
    int error_base = 0;
    int major = 0;
    int minor = 0;
    if (XTestQueryExtension(display, &event_base, &error_base, &major, &minor) == 0) {
        std::cout << "window_x11_real_input: skipped (no XTEST extension)\n";
        XCloseDisplay(display);
        return 0;
    }

    tessera::hal::WindowDesc desc;
    desc.title = "Tessera X11 real input " + std::to_string(static_cast<unsigned long>(getpid()));
    desc.width = 320;
    desc.height = 200;
    desc.visible = true;
    auto window = tessera::hal::create_window(desc);
    if (!expect(window != nullptr, "create_window returns a window")) {
        XCloseDisplay(display);
        return 1;
    }
    const ::Window native = find_window(display, DefaultRootWindow(display), desc.title);
    if (!expect(native != 0, "native window exists") ||
        !expect(wait_until_viewable(display, native, *window), "the window becomes viewable")) {
        XCloseDisplay(display);
        return 2;
    }
    ::Window ignored = 0;
    int origin_x = 0;
    int origin_y = 0;
    XTranslateCoordinates(display, native, DefaultRootWindow(display), 0, 0, &origin_x, &origin_y,
                          &ignored);

    tessera::ui::InputQueue queue(256);
    window->set_input_queue(&queue);
    const Server server{display, native, origin_x, origin_y};
    const float scale = window->metrics().dpi_scale;

    const bool ok =
        pointer_and_wheel(server, *window, queue, scale) && keyboard(server, *window, queue);

    window->set_input_queue(nullptr);
    window.reset();
    XCloseDisplay(display);
    if (!ok) {
        return 3;
    }
    std::cout << "window_x11_real_input: ok\n";
    return 0;
}
